export interface SeedImage {
  /** Miniature Wikimedia Commons (largeur 640 px) ; le nom de fichier ne doit pas contenir de date. */
  url: string;
  alt: string;
  /** Auteur et licence, affichés sur la page des crédits. */
  credit: string;
}

export interface SeedCard {
  title: string;
  /** Année historique : négative avant J.-C. Les titres ne doivent jamais contenir la date. */
  year: number;
  category: "historical" | "cultural";
  /** 3 à 5 phrases, sans nombre à 3 ou 4 chiffres ni « siècle » : visible dès la main. */
  description: string;
  image: SeedImage;
}

const card = (
  category: SeedCard["category"],
  title: string,
  year: number,
  description: string,
  image: SeedImage,
): SeedCard => ({ title, year, category, description, image });

const image = (url: string, alt: string, credit: string): SeedImage => ({ url, alt, credit });

