/** Identifiant stable dérivé du titre : rejouer le seed met à jour sans dupliquer. */
export function seedCardId(title: string): string {
  return title
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}
